() => { const txt=s=>(s||'').replace(/\s+/g,' ').trim(); const minX=innerWidth*0.62;
const vis=e=>{const r=e.getBoundingClientRect();return r.width>0&&r.height>0&&r.left>=minX};
const btns=[...document.querySelectorAll('button')].filter(vis).map(b=>txt(b.getAttribute('aria-label')||b.innerText)).filter(t=>/\b\d{3}\b/.test(t)&&!/^Preview /.test(t)&&!/\$/.test(t));
const groups=[...document.querySelectorAll('div,span,p,h4,h5,h6,legend')].filter(vis).map(e=>txt(e.innerText)).filter(t=>/^(Lacquered MT|Lacquered GL|Wood Veneer|Metal|Lacquered)$/.test(t));
const pressed=[...document.querySelectorAll('button[aria-pressed="true"]')].filter(vis).map(b=>txt(b.getAttribute('aria-label')||b.innerText)).filter(t=>/\b\d{3}\b/.test(t));
const chips=[...document.querySelectorAll('button')].filter(vis).map(b=>txt(b.innerText)).filter(t=>/$|Clear All|^(Material|Color|Look|Price)\b/.test(t)&&t.length<30);
return {count:new Set(btns).size, swatches:[...new Set(btns)], groups:[...new Set(groups)], selected:pressed, chips:[...new Set(chips)]}; }

